import {ADVISOR_POLICIES,ORDINANCES,analyzeOrdinances} from './ordinance-analysis.js?v=country-club-1';
import {changeCivic,ordinanceCost} from './civic.js?v=country-club-1';
import {serializeCity} from './save.js?v=country-club-1';
import {recompute} from './engine.js?v=country-club-1';
const immediate=[['Monthly balance (§)','balance'],['Policy spending (§/month)','cost'],['Policy revenue (§/month)','revenue'],['Resident crime / 100','crime'],['Resident aura / 100','aura'],['Average air pollution / 100','air'],['Power demand','powerDemand'],['Water demand','waterDemand'],['Power delivered','powerDelivered'],['Unserved power demand','powerUnserved'],['Water delivered','waterDelivered'],['Unserved water demand','waterUnserved'],['Operating recycling capacity / month','recyclingCapacity'],['Recyclable share of new garbage (%)','recyclablePercent'],['Peak road traffic','peakTraffic'],['Cleaner industrial buildings','cleanIndustry'],['Average building flammability / 100','flammability']],longTerm=[['Life expectancy target (years)','lifeTarget'],['School-age education target / 100','schoolTarget'],['College-age education target / 100','collegeTarget']];
const fmt=n=>n===null?'Not applicable':n.toLocaleString('en-US',{maximumFractionDigits:2});
const departmentMeasures={utilities:['powerDemand','powerDelivered','powerUnserved','waterDemand','waterDelivered','waterUnserved'],environment:['air','cleanIndustry','recyclingCapacity','recyclablePercent'],transport:['peakTraffic','air','aura'],safety:['crime','flammability'],hea:['crime','aura']};
export function ordinanceComparisonMarkup(result,kind=null){const relevant=key=>!kind||['balance','cost','revenue',...(departmentMeasures[kind]||[])].includes(key)||result.before[key]!==result.after[key];const table=rows=>`<div class="table-scroll"><table><thead><tr><th scope="col">Measure</th><th scope="col">Current</th><th scope="col">Proposed</th><th scope="col">Change</th></tr></thead><tbody>${rows.map(([label,key])=>{const a=result.before[key],b=result.after[key],d=a===null||b===null?null:b-a;return `<tr><th scope="row">${label}</th><td>${fmt(a)}</td><td>${fmt(b)}</td><td>${d===null?'—':(d>0?'+':'')+fmt(d)}</td></tr>`;}).join('')}</tbody></table></div>`;return `<h3>Immediate conditions</h3>${table(immediate.filter(([,key])=>relevant(key)))}${!kind||kind==='hea'||longTerm.some(([,key])=>result.before[key]!==result.after[key])?`<h3>Long-term targets</h3><p>Targets change immediately; residents’ actual learning and life expectancy change over years. These are current-condition targets, not forecasts.</p>${table(longTerm)}`:''}`;}
export function showOrdinanceAnalysis(ui,kind,back){const keys=kind?ADVISOR_POLICIES[kind]:Object.keys(ORDINANCES);if(!keys)throw Error('Choose a department advisor.');const c=ui.city(),$=s=>document.querySelector(s);let draft={...c.civic.ordinances},reviewed=null;
 ui.dialog('Compare ordinances',`<p>Select a policy package, then compare its effects before applying it. Existing service funding stays in effect.</p>${keys.map(key=>`<label class="ordinance"><input type="checkbox" id="comparePolicy-${key}" ${draft[key]?'checked':''}><span>${ORDINANCES[key].name} · §${ordinanceCost(c,key)}/month<br><small>${ORDINANCES[key].description}</small></span></label>`).join('')}<p>${kind?'Other departments’ policies keep their current settings.':'Revenue from parking fines depends on private-car commuting.'}</p><button id="comparePolicies">Compare proposed policies</button><div id="policyComparison" aria-live="polite"></div><p>No month advances during comparison. This projects current development and network conditions; future growth, demographics and disasters can change the outcome. Delivered supply and unmet demand reflect current network connections. Recycling capacity is the total for operating centers; it does not guarantee collection from disconnected neighborhoods. The recyclable share applies to newly produced garbage, not existing waste. Policy descriptions explain other effects not included in the table.</p><button id="applyComparedPolicies" class="primary" disabled>Apply compared policies</button><button id="backPolicyComparison">Back</button>`);
 for(const key of keys)$('#comparePolicy-'+key).onchange=()=>{draft[key]=$('#comparePolicy-'+key).checked;reviewed=null;$('#applyComparedPolicies').disabled=true;$('#policyComparison').innerHTML='<p>Selection changed. Compare again to review this package.</p>';};
 $('#comparePolicies').onclick=()=>{const current=ui.city(),proposal={...current.civic.ordinances};for(const key of keys)proposal[key]=draft[key];const result=analyzeOrdinances(current,proposal);reviewed={source:serializeCity(current),policies:result.ordinances};$('#policyComparison').innerHTML=ordinanceComparisonMarkup(result,kind);$('#applyComparedPolicies').disabled=Object.keys(proposal).every(key=>proposal[key]===current.civic.ordinances[key]);};
 $('#applyComparedPolicies').onclick=()=>{if(!reviewed)return;const current=ui.city();if(serializeCity(current)!==reviewed.source){reviewed=null;$('#applyComparedPolicies').disabled=true;$('#policyComparison').innerHTML='<p>The city changed. Compare again before applying policies.</p>';return;}const result=changeCivic(current,current.civic.funding,reviewed.policies);if(!result.ok)return ui.notify(result.error);recompute(current);ui.clearUndo();ui.update();ui.save();ui.notify('Compared policies applied.');back();};
 $('#backPolicyComparison').onclick=back;
}
